sim.st:
PROGRAM Sim
(* The PLANT, simulated in IEC — so this project runs, moves, and alarms
   with no hardware and no Go. The pump fills the tank against a constant
   demand; the heater warms it against ambient loss.

   A real deployment deletes this task and marks LevelPct/TempC as
   `role: input` in nautilus.yaml, so the field driver supplies them
   instead. Nothing else has to change: the control program reads the same
   tags either way. (Richer physics is the Go tier — see `naut new
   --template sdk-demo`.) *)
VAR_EXTERNAL
    LevelPct : REAL;
    TempC    : REAL;
    SimDtS   : REAL;
    PumpRun  : BOOL;
    Heater   : REAL;
END_VAR

(* tank: pump inflow vs demand, in %/s *)
IF PumpRun THEN
    LevelPct := LIMIT(0.0, LevelPct + 1.7 * SimDtS, 100.0);
ELSE
    LevelPct := LIMIT(0.0, LevelPct - 1.5 * SimDtS, 100.0);
END_IF;

(* thermal: the heater warms, ambient pulls toward 20 °C (equilibrium
   ~80 °C at full heat, so the PI has headroom around its setpoint) *)
TempC := LIMIT(0.0, TempC + (Heater * 0.012 - (TempC - 20.0) * 0.02) * SimDtS, 110.0);
END_PROGRAM

program.fbd:
PROGRAM Demo
(* Control for the heated tank, as an FBD netlist: a seal-in latch for the
   pump, a PI loop whose integral feeds back through a retained variable,
   a TON on-delay for the low-temperature alarm, and the RateOfChange block
   from blocks.st called like any built-in.

   Open the diagram: VS Code -> right-click program.fbd ->
   "Open With -> FBD Diagram". With the controller running, live values
   paint the wires; every gesture in the editor is a structural edit to
   this text. *)
VAR_EXTERNAL
    (* process values — produced by the sim task (sim.st) *)
    LevelPct       : REAL;
    TempC          : REAL;
    ScanDtS        : REAL;
    (* operator setpoints — writable from the dashboard and the tag API *)
    TempSP         : REAL;
    TempLowSP      : REAL;
    Kp             : REAL;
    Ki             : REAL;
    PumpStartLevel : REAL;
    PumpStopLevel  : REAL;
    (* commands + computed state *)
    PumpRun        : BOOL;
    Heater         : REAL;
    TempLowAlm     : BOOL;
    TempRate       : REAL;
END_VAR
VAR
    integral : REAL;
END_VAR
FBD
  NETWORK 'P-101 pump: level hysteresis seal-in'
  // start when low, seal through PumpRun itself, drop out when high
  low  = LE(LevelPct, PumpStartLevel)
  high = GE(LevelPct, PumpStopLevel)
  PumpRun := AND(OR(low, PumpRun), NOT high)

  NETWORK 'TIC-101: temperature PI with anti-windup'
  // the integral is retained state, fed back from its own coil
  e = SUB(TempSP, TempC)
  iStep = MUL(Ki, e, ScanDtS)
  integral := LIMIT(0.0, ADD(integral, iStep), 100.0)
  pTerm = MUL(Kp, e)
  Heater := LIMIT(0.0, ADD(pTerm, integral), 100.0)

  NETWORK 'TAL-101: low temperature, 10 s on-delay'
  // delayed so a transient dip doesn't annunciate; `naut test` asserts
  // this delay exactly
  cold = LT(TempC, TempLowSP)
  a1 : TON(IN := cold, PT := T#10S)
  TempLowAlm := a1.Q

  NETWORK 'Temperature rate of change'
  // a user FUNCTION_BLOCK from blocks.st, instantiated like a built-in
  roc : RateOfChange(IN := TempC, DT := ScanDtS)
  TempRate := roc.OUT
END_FBD
END_PROGRAM

blocks.st:
(* Reusable function blocks for this project — authored in ST, callable
   from ANY IEC language: program.fbd instantiates RateOfChange exactly the
   way it instantiates a built-in TON.

   Every .st file here without a PROGRAM is a library: `naut run`, the
   VS Code extension, `naut check`, and `naut pull` all compose them
   the same way, so online edits round-trip losslessly. *)

FUNCTION_BLOCK RateOfChange
(* Rate of change of IN in units/minute, from the previous scan's value.
   Each instance retains its own prev — across scans and online edits. *)
VAR_INPUT
    IN : REAL;
    DT : REAL; (* seconds since last scan *)
END_VAR
VAR_OUTPUT
    OUT : REAL; (* units per minute *)
END_VAR
VAR
    prev   : REAL;
    primed : BOOL;
END_VAR
IF NOT primed THEN
    prev := IN;
    primed := TRUE;
END_IF;
IF DT > 0.0 THEN
    OUT := (IN - prev) / DT * 60.0;
END_IF;
prev := IN;
END_FUNCTION_BLOCK
